mapper.select:
SELECT PRODUCT_ID, NAME, BRAND, CATEGORY, INGREDIENT, COST, HIT, ELIKE, IMAGE, row_num FROM (
SELECT PRODUCT_ID, NAME, BRAND, CATEGORY, INGREDIENT, COST, HIT, ELIKE, IMAGE, ROW_NUMBER() OVER(ORDER BY PRODUCT_ID desc) AS row_num FROM PRODUCT

		CATEGORY = #{category}



                    	AND NAME LIKE '%' || #{keyword} || '%'


                    	AND BRAND LIKE '%' || #{keyword} || '%'


                    	AND INGREDIENT LIKE '%' || #{keyword} || '%'




	) temp_table WHERE row_num BETWEEN #{begin} AND #{end}
